
import streamlit as st
import pandas as pd

st.set_page_config(
    page_title="Kuku Promo Finder",
    page_icon="🎬",
    layout="wide",
)

st.title("🎬 AI-Powered Promo Finder")
st.caption(
    "Explore and rank screenplay promo candidates using structured events and AI editorial scores."
)

st.info(
    "Prototype dashboard: upload the CSV outputs generated by the local pipeline. "
    "The public repository should contain code only—do not commit the confidential screenplay pack or real outputs."
)

# -----------------------------
# File Upload
# -----------------------------
with st.sidebar:
    st.header("Upload pipeline outputs")

    shortlist_file = st.file_uploader(
        "candidate_shortlist.csv (recommended)",
        type=["csv"],
        key="shortlist",
    )

    evaluation_file = st.file_uploader(
        "ai_evaluation_full.csv (optional)",
        type=["csv"],
        key="evaluation",
    )

    st.divider()

    st.caption(
        "Expected evaluation fields include candidate_id, hook_score, "
        "cliffhanger_score, context_score, emotion_score and verified_score."
    )


def load_csv(uploaded_file):
    if uploaded_file is None:
        return None

    try:
        return pd.read_csv(uploaded_file)
    except Exception as exc:
        st.error(f"Could not read {uploaded_file.name}: {exc}")
        return None


shortlist = load_csv(shortlist_file)
evaluation = load_csv(evaluation_file)


# -----------------------------
# Instructions if no file uploaded
# -----------------------------
if shortlist is None:
    st.subheader("How to use this prototype")

    st.markdown(
        """
        1. Run the local parsing, candidate-generation and shortlist scripts.
        2. Upload `candidate_shortlist.csv` using the sidebar.
        3. Upload `ai_evaluation_full.csv` when AI evaluations are available.
        4. Filter candidates by episode, verdict and score to inspect promising promo moments.
        """
    )

    st.warning("Upload candidate_shortlist.csv to begin.")
    st.stop()


# -----------------------------
# FIXED: Generate candidate IDs
# -----------------------------
shortlist = shortlist.copy()

if "candidate_id" not in shortlist.columns:
    shortlist = shortlist.reset_index().rename(
        columns={"index": "candidate_id"}
    )

shortlist["candidate_id"] = pd.to_numeric(
    shortlist["candidate_id"], errors="coerce"
)

shortlist = shortlist.dropna(subset=["candidate_id"])

shortlist["candidate_id"] = shortlist["candidate_id"].astype(int)


# -----------------------------
# Process AI Evaluation
# -----------------------------
if evaluation is not None:

    if "candidate_id" not in evaluation.columns:
        st.error("ai_evaluation_full.csv must contain candidate_id.")
        st.stop()

    evaluation = evaluation.copy()

    evaluation["candidate_id"] = pd.to_numeric(
        evaluation["candidate_id"], errors="coerce"
    )

    evaluation = evaluation.dropna(subset=["candidate_id"])

    evaluation["candidate_id"] = evaluation["candidate_id"].astype(int)

    detail_cols = [
        c for c in shortlist.columns
        if c not in evaluation.columns
    ]

    if detail_cols:
        evaluation = evaluation.merge(
            shortlist[["candidate_id"] + detail_cols],
            on="candidate_id",
            how="left",
        )

    data = evaluation

else:
    data = shortlist.copy()


# -----------------------------
# Score Processing
# -----------------------------
score_col = (
    "verified_score"
    if "verified_score" in data.columns
    else None
)

if score_col:
    data[score_col] = pd.to_numeric(
        data[score_col], errors="coerce"
    )


# -----------------------------
# Pipeline Snapshot
# -----------------------------
st.subheader("Pipeline snapshot")

m1, m2, m3 = st.columns(3)

m1.metric(
    "Shortlisted candidates",
    f"{len(shortlist):,}"
)

evaluated_count = (
    data["candidate_id"].nunique()
    if evaluation is not None
    else 0
)

m2.metric(
    "AI-evaluated candidates",
    f"{evaluated_count:,}"
)

m3.metric(
    "Not yet AI-evaluated",
    f"{max(len(shortlist) - evaluated_count, 0):,}"
)

if evaluation is None:
    st.warning(
        "Only shortlist data is loaded. AI scores and verdicts "
        "will appear after you upload ai_evaluation_full.csv."
    )


# -----------------------------
# Explore Candidates
# -----------------------------
st.subheader("Explore candidates")

filtered = data.copy()

col1, col2, col3 = st.columns(3)

if "episode" in filtered.columns:

    episodes = sorted(
        filtered["episode"].dropna().astype(str).unique().tolist()
    )

    selected_episodes = col1.multiselect(
        "Episode",
        episodes,
        default=episodes,
    )

    filtered = filtered[
        filtered["episode"].astype(str).isin(selected_episodes)
    ]


if "verdict" in filtered.columns:

    verdicts = sorted(
        filtered["verdict"].dropna().astype(str).unique().tolist()
    )

    selected_verdicts = col2.multiselect(
        "AI verdict",
        verdicts,
        default=verdicts,
    )

    filtered = filtered[
        filtered["verdict"].astype(str).isin(selected_verdicts)
    ]


if score_col:

    numeric_scores = filtered[score_col].dropna()

    if not numeric_scores.empty:

        min_score = float(numeric_scores.min())
        max_score = float(numeric_scores.max())

        threshold = col3.slider(
            "Minimum verified score",
            min_value=round(min_score, 1),
            max_value=(
                round(max_score, 1)
                if max_score > min_score
                else round(min_score + 0.1, 1)
            ),
            value=round(min_score, 1),
            step=0.1,
        )

        filtered = filtered[
            filtered[score_col] >= threshold
        ]


if score_col:
    filtered = filtered.sort_values(
        score_col,
        ascending=False
    )


# -----------------------------
# Display Candidate Table
# -----------------------------
preferred = [
    "candidate_id",
    "episode",
    "start_time",
    "end_time",
    "duration",
    "verified_score",
    "verdict",
    "hook_score",
    "cliffhanger_score",
    "context_score",
    "emotion_score",
]

display_cols = [
    c for c in preferred
    if c in filtered.columns
]

if not display_cols:
    display_cols = list(filtered.columns)


st.dataframe(
    filtered[display_cols],
    use_container_width=True,
    hide_index=True,
)

st.caption(
    f"Showing {len(filtered):,} of {len(data):,} loaded rows."
)


# -----------------------------
# Candidate Details
# -----------------------------
st.subheader("Candidate detail")

if not filtered.empty:

    ids = filtered["candidate_id"].astype(int).tolist()

    chosen_id = st.selectbox(
        "Select candidate ID",
        ids,
    )

    chosen = filtered[
        filtered["candidate_id"] == chosen_id
    ].iloc[0]

    left, right = st.columns([1, 2])

    with left:

        st.markdown(
            f"**Candidate:** {int(chosen['candidate_id'])}"
        )

        if "episode" in chosen:
            st.markdown(f"**Episode:** {chosen['episode']}")

        if "start_time" in chosen and "end_time" in chosen:
            st.markdown(
                f"**Time:** {chosen['start_time']} – {chosen['end_time']}"
            )

        if score_col and pd.notna(chosen.get(score_col)):
            st.metric(
                "Verified score",
                f"{chosen[score_col]:.2f}/10"
            )

        if "verdict" in chosen:
            st.markdown(f"**Verdict:** {chosen['verdict']}")

    with right:

        for field, label in [
            ("hook_explanation", "Hook assessment"),
            ("cliffhanger_explanation", "Cliffhanger assessment"),
            ("context_explanation", "Context assessment"),
            ("why_it_works", "Why it works"),
        ]:

            value = chosen.get(field)

            if pd.notna(value) and str(value).strip():
                st.markdown(f"**{label}**")
                st.write(value)

    if "content" in chosen and pd.notna(chosen["content"]):

        with st.expander("Screenplay segment text"):
            st.write(chosen["content"])

else:
    st.info("No candidates match the selected filters.")


# -----------------------------
# Footer
# -----------------------------
st.divider()

st.caption(
    "Scores are editorial decision-support signals, not ground truth. "
    "Review the screenplay segment before selecting or publishing a promo."
)

